from review_schema import A

for refs,title,desc,other in [('5:2.1','Mughal animal carpet — possibly Lahore','The cropped red field shows two running antelope-like animals among large scrolling flowers. A black animal crosses above a pale brown one; the full border is outside the crop.','Silk animal carpet — Iran'),('5:2.2','Silk animal carpet — Iran','A red rectangular field contains varied animals among curling stems. Multiple narrow borders and a broad dark floral border enclose it; repeated pale blossoms mark the outer edge.','Mughal animal carpet — possibly Lahore')]:
 A(refs,title,'T',{'Field & Border Organization':desc,'Technique':'Carpet structure is visible as a woven surface; the photograph cannot resolve knot type or density.','Dyes & Materials':'The Iranian example is captioned silk. Red, green, cream and dark blue are visible colours, not chemical dye identifications.','Function & Circulation':'The slide compares North Indian and Iranian carpets under exchange of skills and Mughal conquest of Gujarat. Production location and present collection are separate metadata.'},'animal-motifs floral-trade carpet',sig='economic/trade=The explicit comparison connects textile making with interregional exchange.|social=Transfer of skilled craft knowledge is a distinct part of the argument.|visual/aesthetic=Animals and vegetal scrolls share a field while the two carpets remain separate objects.',dist='Similar animal-and-flower vocabulary does not establish that the carpets came from one workshop or use identical materials.',compare=[{'target':other,'relationship':'parallel','reason':'Explicit pairing of Iranian and North Indian carpets on slide 2.'}])
for refs,title,desc in [('5:3.1','Revived Dhaka muslin sari','Pale cloth is gathered through a small ring at centre, spreading into broad folds on either side against a dark background.'),('5:3.2','Dhaka muslin — transparency demonstration','A spread hand is clearly visible through a pale sheer textile; fine orthogonal threads can be seen where the cloth crosses the fingers.')]:
 A(refs,title,'T',{'Technique':'A fine woven textile; the slide does not specify loom, thread count or precise historical reconstruction method.','Field & Border Organization':desc,'Dyes & Materials':'Muslin, a fine cotton textile, is the lecture identification; the nearly white colour does not establish bleaching or dye history.','Function & Circulation':'The left image documents a revived sari in Dhaka; the right demonstrates sheerness. Both introduce Bengal muslin as a prized trade good.'},'muslin craft-agency',sig='economic/trade=The heading identifies muslin as a prized Bengal commodity.|social=The revival image connects historical prestige with living textile skill.|visual/aesthetic=Transparency and compressibility supply visual evidence of fineness.',dist='These modern illustrations are not securely dated surviving Mughal garments; do not transfer the lecture’s historical frame into an object date.')
A('5:4.1','Akbar and Adham Khan','P',{'Composition':'A palace terrace occupies the upper half; a falling inverted figure connects it to a crowded lower court. Horizontal text bands divide the image without stopping the downward narrative movement.','Perspective Convention':'Tilted balconies, stacked interiors and a steep stairway expose several spaces at once. This is narrative spatial organization, not an unsuccessful single-point perspective.','Figural Style':'Robes, turbans and contrasting coloured garments distinguish court figures; gesture and falling bodies communicate conflict.','Text–Image Relationship':'Calligraphy runs through upper and lower registers and along the bottom margin.','Motifs & Hidden Details':'Tiny birds occupy the upper-right architectural compartment; patterned carpets and wall tiles distinguish courtly surfaces.'},'mughal-atelier costume orientalism-occidentalism',sig='political=The lecture links sartorial choice with a ruler’s legitimacy and Mughal pluralism.|visual/aesthetic=Architecture organizes several moments of a violent court episode.',dist='Occidentalism is raised as a question beside the image; it is not a secure attribution of every costume to Europe.')
A('5:5.1,6.2','The Virgin and Child — Basawan','P',{'Composition':'A reclining nursing mother and child occupy the lower right, with a pavilion rising behind and an open garden at left. Nested floral and calligraphic borders make the image an album page.','Perspective Convention':'The carpet is tilted up; the pavilion has oblique columns and roof beams, while landscape and figures retain different spatial scales.','Palette & Pigment':'Green clothing, orange drapery, blue cushions and a gold-coloured carpet dominate. Opaque watercolour and gold are captioned, unlike inferred pigment names.','Figural Style':'The mother rests on cushions with one hand near her cheek; the infant twists against her breast.','Motifs & Hidden Details':'An open book rests on a red cushion at left. A pale cat runs at lower right toward a shallow dish; a gold-coloured ewer stands at lower left. Behind them are a resting deer-like animal, a round well or basin, thatched structures and a small tree.','Text–Image Relationship':'Calligraphic cartouches above and below are visually integrated with illumination; their content is not translated here.','Subject Matter vs Technique Origin':'Christian maternal imagery is reworked in a Mughal painted album page with local furnishings and a Persianate border.'},'christian-adaptation muraqqa firangi-sazi animal-motifs',sig='religious/cosmological=The subject belongs to Christian devotional imagery.|visual/aesthetic=The reclining pose, garden, cat and domestic furnishings elaborate the borrowed theme.|social=The named Mughal artist has creative agency in the adaptation.',dist='The nineteenth-century painting after Luini on slide 6 cannot be the direct source for a painting dated around 1590.|Christian iconography does not establish that Basawan or the patron converted.',compare=[{'target':'Nursing Virgin and Child — after Luini','relationship':'parallel','reason':'The lecture compares the maternal subject; chronology excludes direct copying of this later object.'}])
A('5:6.1','Nursing Virgin and Child — after Luini','P',{'Composition':'A seated mother and nursing child fill the foreground against a dark interior. A small rectangular opening at upper left reveals trees, a house and distant hills.','Perspective Convention':'Soft modelling gives faces and bodies volume; the window establishes a secondary deep landscape.','Palette & Pigment':'Red dress and blue lower drapery contrast with pale flesh and dark background.','Figural Style':'The child sits upright on the mother’s lap and reaches toward her breast; the mother’s downward gaze closes the pair into an intimate group.'},'christian-adaptation naturalism',sig='visual/aesthetic=The paired slide compares different compositional treatments of a nursing Virgin.|religious/cosmological=The caption identifies a Christian mother-and-child subject.',dist='“After Bernardino Luini” means a later work based on his art; the caption dates this object to the nineteenth century, not Luini’s lifetime.',compare=[{'target':'The Virgin and Child — Basawan','relationship':'parallel','reason':'Shared theme, contrasting pose, setting and chronology.'}])
A('5:7.1','Akbar and an armed combat of ascetics','P',{'Composition':'A dense knot of combatants fills the lower two-thirds; the mounted ruler and court attendants occupy the calmer upper band. A distant settlement sits beyond trees at the top.','Perspective Convention':'The high viewpoint exposes many overlapping bodies, weapons and shields; distance is organized by vertical stacking and diminishing figures.','Figural Style':'Bare or lightly clothed ascetics wield curved blades, staffs and circular shields, contrasting with the elaborate dress of the ruler’s party.','Motifs & Hidden Details':'Two elephants and a red parasol stand at upper right; a decorated standard rises near the rider; round weapon-like rings punctuate the melee.','Line & Hand':'Fine contour separates many entwined limbs. The caption credits Basawan; the lecture explains a collaborative Persianate–Indian atelier rather than a culturally isolated hand.'},'mughal-atelier persianate',sig='political=The ruler is placed above and apart from the combat.|social=The lecture emphasizes collaboration and manuscript circulation in Akbar’s workshop.|visual/aesthetic=Contrasting density and composure differentiate battle and sovereign presence.',dist='A scene with ascetics is not necessarily a devotional image; here the subject is armed conflict viewed within a court narrative.')
A('5:8.1','Virgin of the Rocks','P',{'Composition':'Four figures form a pyramidal group in a rocky grotto. The mother’s head crowns the group, with the two children low at either side and an angel at right.','Perspective Convention':'Pale blue distant peaks recede behind darker rock openings; graduated light and shade give faces and limbs volume.','Line & Hand':'Soft tonal transitions around faces exemplify the slide’s term sfumato; not every edge is equally blurred.','Motifs & Hidden Details':'The left child clasps hands near a thin cross-shaped staff; the lower-right child raises a blessing hand; small flowering plants occupy the foreground ledge.','Palette & Pigment':'Blue drapery and distant blue landscape punctuate brown-green rock and pale flesh.'},'sfumato perspective christian-adaptation',sig='visual/aesthetic=The lecture isolates modelling, atmospheric recession and sfumato as Renaissance pictorial resources.',dist='Sfumato describes soft tonal transition; it is not synonymous with single-point linear perspective or with all European painting.')
A('5:9.1','Akbar’s Church — Agra','A',{'Building Type & Function':'Christian church, captioned Agra and associated by the lecture with Akbar’s religious interests.','Elevation & Massing':'The photograph shows a white colonnaded entrance under a triangular pediment, a rear dome, small tower-like projections and crosses.','Structural System':'Columns and a horizontal entablature give the porch a trabeated form; the rear dome adds an arcuate form. The picture does not date these visible phases.','Plan & Spatial Organization':'A landscaped foreground leads to the central porch; the complete interior plan is not shown.','Materials & Construction Technique':'White rendered surfaces conceal underlying masonry; structural materials cannot be determined from colour alone.'},'trabeate-arcuate christian-adaptation',sig='religious/cosmological=The church provides architectural evidence for the lecture’s discussion of multiple religious communities.|political=The teaching context relates religious diversity to Akbar’s rule.',dist='The lecture’s 1580s date does not prove that the photographed neoclassical-looking porch survives unchanged from that decade.',uncertain=['Chronology of the visible building phases is not established by the slide.'])
A('5:10.1,17.1','The Deposition from the Cross — Mughal','P',{'Composition':'Christ’s descending body lies diagonally between two ladders on either side of the cross. Mourners cluster below, and an added celestial register fills the upper blue sky.','Perspective Convention':'Figures and ladders form a deep triangular scaffold; the background combines distant architecture and small secondary groups in a compressed landscape.','Palette & Pigment':'Blue cloud forms, green landscape and bright orange-yellow drapery replace the monochrome tonal structure of the comparison engraving.','Motifs & Hidden Details':'Winged children and trumpet-playing angels float across the top. A skull and long bones occupy the foreground; small pale and brown animals stand at lower right; a standing winged attendant appears on the right edge.','Subject Matter vs Technique Origin':'A European Christian composition is adapted as Mughal gouache on paper, with a floral album border and added figures.'},'firangi-sazi christian-adaptation halo-angels',sig='religious/cosmological=The Passion narrative remains recognizable.|visual/aesthetic=Colour, celestial additions and framing transform the borrowed composition.|social=The alteration makes artistic agency visible even though the painter is unnamed.',dist='Derivative identifies a source relationship, not a lack of invention.|The Mughal painting is not itself an engraving.',compare=[{'target':'Descent from the Cross — Raimondi after Raphael','relationship':'derivative','reason':'The paired compositions share the cross, ladders and descending body, while the Mughal version visibly alters the setting and figures.'}])
A('5:11.1','Canteen with Christian imagery','M',{'Form & Function':'A flattened circular container has a short neck and curved suspension loops. The broad circular face provides a continuous decorated field.','Technique':'Brass with silver inlay is specified by the caption. Pale figures and inscriptions stand against darker metal; the image alone does not establish remaining original silver coverage.','Decorative Vocabulary':'A central enthroned mother-and-child group is surrounded by inscriptions, circular medallions and bands of small figures.','Subject Matter vs Technique Origin':'Christian imagery appears on inlaid metalwork made in Syria or northern Iraq, rather than on a European painted panel.'},'inlay christian-adaptation calligraphy',sig='religious/cosmological=The object provides an earlier example of Christian imagery in an Islamicate cultural setting.|visual/aesthetic=Figural medallions and calligraphic bands coexist on a functional vessel.',dist='This mid-thirteenth-century object predates the Safavid and Mughal empires named in the slide heading; it serves as comparative background.')
A('5:11.2','The Birth of the Prophet Muhammad','P',{'Composition':'A horizontal interior scene is divided by two slender red columns. A reclining woman occupies the centre-right bed, surrounded by attendants; a seated figure at far right occupies a separate compartment.','Figural Style':'Layered patterned garments, lowered heads and clustered hands focus attention on the newborn at centre-left.','Motifs & Hidden Details':'Large wings extend behind two central attendants; a small hanging lamp appears above the bed; curtains frame the far-right space.','Text–Image Relationship':'A line of script runs above the illustration in the historical manuscript.','Perspective Convention':'The room is opened laterally, with overlapping figures and tilted bed rather than a single vanishing point.'},'halo-angels persianate manuscript-history',sig='religious/cosmological=The caption identifies Muhammad’s birth within Rashid al-Din’s world history.|visual/aesthetic=Courtly manuscript conventions frame a religious historical episode.',dist='This is an Ilkhanid manuscript image around 1314, not a Mughal image of the Virgin and Child despite its placement in a comparative slide.')
A('5:12.1','Virgin and Child — Ghulam','P',{'Composition':'A seated mother with bent knees supports a twisting child within a mostly empty pale field, surrounded by a blue-and-gold-coloured scrolling border.','Line & Hand':'Fine dark outlines and restrained wash define folds, face and limbs; the limited colour makes drawing particularly prominent.','Figural Style':'The mother inclines her head and wears a veil and necklaces; her seated posture spreads the drapery across the bottom.','Text–Image Relationship':'Small inscriptions appear at lower left of the figure; the slide reports that the work was made for Prince Salim.','Subject Matter vs Technique Origin':'A Christian maternal theme is translated into a Mughal ink, opaque-watercolour and gold album image; printed European imagery is part of the lecture’s explanation.'},'christian-adaptation firangi-sazi muraqqa',sig='political=The inscription as reported links the work to Prince Salim.|religious/cosmological=Christian imagery participates in a court collecting texts from several traditions.|visual/aesthetic=The drawing adapts pose and drapery into a different material and album format.',dist='The Plantin Bible is a circulation context named in the lecture; the slide does not identify an exact page as this drawing’s immediate model.')
for refs,title,desc,other in [('5:13.1','Camel Fight — ascribed to Bihzad','Two camels interlock their necks on a pale rocky ground; three handlers surround them. A text box fills the upper-right corner, and small trees punctuate the blue background.','Camel Fight — Abd al-Samad'),('5:13.2','Camel Fight — Abd al-Samad','Two richly blanketed camels wrestle at lower centre; three handlers occupy the corners around them. Tall knotted rocks fill the upper-left background, with a tree and raised whip at right. Two text panels interrupt the upper sky.','Camel Fight — ascribed to Bihzad')]:
 A(refs,title,'P',{'Composition':desc,'Perspective Convention':'The animals are modelled through contours and shading, while the high ground plane exposes their entangled limbs.','Figural Style':'Handlers use ropes and raised arms to engage with the fighting animals. Distinct clothes and animal coverings add local detail.','Text–Image Relationship':'Calligraphic panels form part of the page composition; the lecture uses the pair to discuss lineage or silsila.'},'silsila persianate animal-motifs',sig='social=Artistic lineage is discussed through a repeated subject and recognizably related design.|visual/aesthetic=The later version changes scale, rocks, vegetation and treatment while retaining the camel encounter.',dist='These are separate works, not two reproductions of one painting.|The heading about a woman artist supplies no name or secure attribution for either image.',compare=[{'target':other,'relationship':'derivative' if 'Samad' in title else 'parallel','reason':'Abd al-Samad’s later reworking is compared with the earlier attributed model as a study of artistic lineage.'}])
A('','Pigment preparation — V&A video still','F',{'Subject & Evidence':'Hands hold a dark bowl of green-blue granular material over a mortar and pestle. This makes preparation work visible within a module otherwise dominated by finished paintings.','Studio vs Documentary Context':'A demonstration video still with V&A branding; no maker or exact pigment is identified in the slide.'},'craft-agency pigment-evidence',sig='social=Material preparation is a skilled part of painting production.|visual/aesthetic=The still redirects attention from depicted colour to its manufacture.',dist='Green-blue appearance alone cannot identify malachite, azurite or a chemical recipe.',slides='5:14')
A('5:15.1','Crucifixion — Dürer attribution queried','R',{'Process':'A monochrome line print with dense directional hatching; the slide queries Dürer’s attribution and gives 1511. Specific technique requires catalogue confirmation.','Composition & Motifs':'Christ occupies the upper cross; the mourning woman stands at lower left and Saint John at lower right. A skull lies at the foot; INRI appears above and a monogram at lower right.','Edition & Circulation':'The comparison demonstrates how a European printed figure could circulate as a model in a Mughal workshop.','Subject Matter vs Technique Origin':'European Christian imagery and a European print are distinguished from the Mughal brush study made after one figure.'},'christian-adaptation print-transfer',sig='visual/aesthetic=The full crowded print allows the selected figure in Abu’l Hasan’s study to be located.',dist='The question mark in the lecture’s attribution must remain until an independent catalogue confirms this print.',compare=[{'target':'Saint John the Evangelist after Dürer','relationship':'derivative','reason':'The Mughal study isolates and adapts the lower-right figure from a Dürer-related model.'}],uncertain=['Caption explicitly queries attribution; precise print catalogue identity unresolved.'])
A('5:15.2','Saint John the Evangelist after Dürer','P',{'Composition':'A single standing figure fills a narrow pale sheet, with the surrounding Crucifixion scene removed.','Figural Style':'Curly hair, lifted gaze, clasped hands and voluminous angular drapery repeat the comparison figure’s mourning pose.','Line & Hand':'Light contour and sparse tonal shading replace the dense hatching of the print. Several lower folds remain faint.','Text–Image Relationship':'Small marginal inscriptions run along the lower and right edges.','Subject Matter vs Technique Origin':'European Christian subject matter is rendered in a Mughal brush drawing with gouache, not by reproducing the engraved matrix.'},'print-transfer firangi-sazi christian-adaptation',sig='social=The named artist’s study provides evidence of workshop learning through selection and adaptation.|visual/aesthetic=Isolation changes the figure’s visual emphasis and allows scrutiny of drapery and gesture.',dist='The drawing is not an independent eyewitness depiction of Saint John or a European print impression.',compare=[{'target':'Crucifixion — Dürer attribution queried','relationship':'derivative','reason':'The paired slide makes the selected pose and drapery relationship explicit.'}])
A('5:16.1','Abdullah Khan Uzbek Hawking','P',{'Composition':'A mounted figure faces a standing falconer in the lower half, while red rocks, a river and small trees occupy the expansive background. Nested floral borders enclose the scene.','Palette & Pigment':'Intense red ground and rocks contrast with a blue saddle cloth, green turf and pale violet sky; pigment identities are not supplied.','Motifs & Hidden Details':'A small dog runs between horse and falconer; a perched hunting bird rests on the falconer’s gloved hand; a quiver projects behind him; small flowering plants line the very bottom.','Perspective Convention':'The horizon is high and the landscape stacks upward; the foreground meeting remains clearly legible within it.'},'animal-motifs muraqqa royal-devotion',sig='political=Hawking and attended riding give the named elite figure a courtly identity.|visual/aesthetic=Strong red landscape and floral frame produce an idealized setting.',dist='The subject’s Uzbek identity does not change the captioned Mughal production context or make the painting a European hunting print.')
A('5:17.2','Descent from the Cross — Raimondi after Raphael','R',{'Process':'Engraving, an intaglio process, is specified. Dense parallel and cross-hatched lines give tone to bodies, cloth and the receding landscape.','Composition & Motifs':'Two ladders flank the cross. Workers lower Christ diagonally; mourners gather at its base. A large tree frames the right edge and a distant town fills the horizon.','Edition & Circulation':'The print is an image after Raphael, itself a reproductive relationship before its comparison with Mughal painting.','Subject Matter vs Technique Origin':'European Christian narrative circulates through a reproducible engraved image; the Mughal adaptation uses painted colour.'},'engraving print-transfer christian-adaptation',sig='visual/aesthetic=The structural arrangement supplies a comparative model while the Mughal image changes details and framing.',dist='Raimondi is the engraver and Raphael the named design source; the credits are not interchangeable.',compare=[{'target':'The Deposition from the Cross — Mughal','relationship':'derivative','reason':'The Mughal work adapts the composition shown alongside this engraving.'}])
A('5:18.1','Composite European print and Persian drawings — Gulshan album','P',{'Composition':'A calligraphic band spans the top; a small Luna print occupies upper left, a seated man the middle left, three men the right, and a reclining lion the bottom. A wide floral margin with small coloured birds surrounds them.','Text–Image Relationship':'The album preserves differently styled fragments and scripts rather than forcing them into one continuous narrative.','Line & Hand':'Dark print hatching, lightly outlined figures and the shaded lion visibly differ; the lecture mentions Riza Abbasi without allocating every component to a hand.','Perspective Convention':'Each inset has its own spatial convention. The page’s unity comes from framing and arrangement.','Subject Matter vs Technique Origin':'A European print is physically combined with drawings and illuminated album framing.'},'muraqqa silsila print-transfer',sig='political=The lecture treats collecting and arranging artistic lineages as a claim to connection.|visual/aesthetic=Difference of style is retained and made legible within a single page.',dist='One assembled folio need not have one artist or production date; dates of component images and assembly differ.')
A('5:18.2','Luna — print inset in the Gulshan album','R',{'Process':'The lecture identifies this as a European print; tiny hatching is visible, but the slide does not specify the matrix or printmaker.','Composition & Motifs':'At the upper left of the folio, a woman holds a crescent while riding through clouds in a chariot; boats and a shore appear below. LVNA labels the figure above.','Edition & Circulation':'Its placement in a Mughal album is direct material evidence of image circulation.','Subject Matter vs Technique Origin':'Roman lunar subject matter and European printmaking are incorporated into a Mughal album context.'},'muraqqa print-transfer luna',sig='visual/aesthetic=The inset’s hatching and cloud-borne figure contrast with nearby Persian drawings.|economic/trade=The imported printed component makes circulation tangible, although its route is not specified.',dist='Luna belongs to the small printed component, not to every figure on the composite folio.',uncertain=['Printmaker, process and precise edition not supplied.'])
for refs,title,desc in [('5:18.3','Seated man — Gulshan composite folio','A bearded seated man turns right beneath swirling cloud lines. His robe has broad empty surfaces and delicate contours; one hand reaches toward a small plant.'),('5:18.4','Three men — Gulshan composite folio','Two standing turbaned men occupy the upper right above a seated bearded man. Their robes and headgear are defined mainly by light contours against vegetal ornament.'),('5:18.5','Reclining lion — Gulshan composite folio','A large tawny lion stretches along the bottom band, head at right and tail curling left; dark shading concentrates around the mane and back. Small flowering plants fill the surrounding ground.')]:
 A(refs,title,'P',{'Composition':desc,'Text–Image Relationship':'This is an individual component within an assembled folio, not an independent fully captioned sheet in the lecture.','Line & Hand':'The visible style is compared with adjacent fragments. No component-specific attribution is inferred from the general reference to Riza Abbasi.'},'muraqqa silsila',sig='visual/aesthetic=The component contributes a distinct style to an album organized around artistic difference.',dist='Do not assign this inset to Riza Abbasi solely because his name appears in the slide’s thematic text.',uncertain=['Individual attribution and date are not assigned by the lecture.'])
A('5:19.1,20.1','Jahangir shooting the head of Malik Anbar on a cosmic globe','P',{'Composition':'The ruler stands centrally on a globe and draws a bow toward the severed head on a tall pole at left. The globe rests above a red bull and a large fish, establishing a vertical cosmic axis.','Perspective Convention':'The rounded globe is modelled and geographically marked, but it serves allegory rather than an optically plausible space. Slide 20 enlarges the Indian landmass and small animals on its surface.','Figural Style':'Pink patterned robe, jewelled belt, turban and firm archery pose give Jahangir controlled authority.','Motifs & Hidden Details':'An owl perches over the enemy’s head at upper left; a balance hangs below the bow. Winged figures carrying objects occupy the upper sky. A bird-like golden form appears to the right of the ruler; an ornate upright standard stands at lower right. The bull is supported by the fish, not the reverse.','Text–Image Relationship':'Short inscriptions are dispersed around figures and objects; they are not translated from this reproduction.','Subject Matter vs Technique Origin':'European-style terrestrial cartography is combined with Mughal imperial portraiture and the lecture’s Islamic cosmological fish–bull support system.'},'cosmic-globe cartography halo-angels balance owl',sig='political=The image asserts the ruler’s symbolic dominance over an enemy and the world.|religious/cosmological=The fish and bull locate sovereignty within a cosmic order.|visual/aesthetic=Cartographic modelling and emblematic scale coexist in a deliberately impossible scene.',dist='This is a symbolic victory image, not evidence that Jahangir personally shot Malik Anbar.|The lecture asks about an Antwerp globe; it does not identify the exact globe model as certain.',compare=[{'target':'Jahangir embracing Shah Abbas on a globe','relationship':'parallel','reason':'Both use cartographic form for imperial allegory, with different political scenarios.'}])
A('5:21.1','Jahangir embracing Shah Abbas on a globe','P',{'Composition':'A taller Jahangir at right embraces a smaller Shah Abbas at left before an enormous radiant disk and crescent. Their feet rest over animals on a partial terrestrial globe.','Figural Style':'Contrasting stature, turbans, jewelled dress and hand placement establish an unequal pairing despite the embrace.','Motifs & Hidden Details':'A lion lies under Jahangir, a pale lamb-like animal under Shah Abbas. Winged heads support the crescent at both sides. The enlarged detail shows a foot positioned over the Indian landmass.','Perspective Convention':'The mapped sphere gives geographic specificity to an impossible cosmic stage.','Palette & Pigment':'Gold-coloured radiance, turquoise sky, pink and green robes and layered floral borders heighten the ceremonial effect.'},'cosmic-globe cartography halo-angels lion-lamb',sig='political=The lecture reads the globe as symbolic possession; differences of scale visibly privilege Jahangir.|religious/cosmological=Celestial light and peaceful animals idealize the sovereign order.|visual/aesthetic=Embrace, radiant disk and mapped earth combine several representational conventions.',dist='The scene is allegorical; it should not be used as documentary proof that the two rulers met in this setting.',compare=[{'target':'Jahangir shooting the head of Malik Anbar on a cosmic globe','relationship':'parallel','reason':'Shared imperial globe device, contrasting embrace and aggression.'}])
for refs,title,desc,other in [('5:22.1','Jahangir — Hashim, shared folio','The upper compartment contains a jewelled profile ruler behind a decorated parapet, holding a small round object. A radiating halo outlines his head against the dark field.','Jesus — Abu’l Hasan, shared folio'),('5:22.2','Jesus — Abu’l Hasan, shared folio','The lower compartment shows a youthful haloed figure in green with lowered head, holding a tall cross diagonally beside his face.','Jahangir — Hashim, shared folio')]:
 A(refs,title,'P',{'Composition':desc,'Text–Image Relationship':'The two paintings share one folio with narrow inscriptions and a wide floral border. Separate artist/date credits are supplied for upper and lower images.','Subject Matter vs Technique Origin':'Mughal court portraiture and Christian subject matter are brought into one album arrangement; common framing does not make their subjects identical.'},'muraqqa halo-angels christian-adaptation',sig='political=The ruler’s portrait is placed in direct vertical relationship with a sacred image.|religious/cosmological=The cross and halo identify the lower image’s Christian field of reference.|visual/aesthetic=Shared framing creates a deliberate dialogue between two distinct pictures.',dist='The common accession 07A.12 belongs to the shared folio; it does not justify merging Jahangir and Jesus into one depicted person or one artist’s work.',compare=[{'target':other,'relationship':'complementary','reason':'Upper and lower components are physically assembled on the same folio.'}])
A('5:23.1,24.1','Shah Jahan on a Terrace Holding a Portrait Pendant','P',{'Composition':'A standing ruler on a small yellow platform occupies the centre of a terrace, below a vast radiant halo. Receding water and trees lie behind a low white screen.','Perspective Convention':'The platform and patterned carpet recede obliquely, while the profile body retains a formal frontal-plane presentation.','Figural Style':'A pink floral robe, plumed turban, necklaces, sash and sword frame the small raised pendant containing the ruler’s own portrait.','Motifs & Hidden Details':'Winged figures appear at the upper corners and top centre; tiny boats dot the water; white pierced railing panels stand behind the platform.','Text–Image Relationship':'Calligraphy frames the inner image, then coloured floral and broad gold-coloured margins surround it.','Subject Matter vs Technique Origin':'Mughal imperial self-representation incorporates radiating halo, angels and spatial devices discussed as European elements in the lecture.'},'halo-angels perspective muraqqa portrait-miniature',sig='political=Portrait within portrait multiplies the sovereign’s representation.|visual/aesthetic=Imported motifs are integrated into a highly ordered Mughal album image.',dist='The halo and angels are adapted visual resources, not evidence that the subject is a Christian saint.',compare=[{'target':'Standing ruler drawing — possibly Rembrandt','relationship':'parallel','reason':'Slide 24 pairs the Mughal portrait with a European drawing while the exact source relationship remains unproved.'}])
A('5:24.2','Standing ruler drawing — possibly Rembrandt','P',{'Composition':'A standing profile ruler faces left on an otherwise nearly blank sheet. One hand raises a small stem-like object, while the other rests near a sword hilt.','Line & Hand':'Loose brown linear strokes and light hatching give the figure volume; folds and accessories are abbreviated compared with the dense coloured Mughal portrait.','Figural Style':'A wrapped turban, necklaces, long coat and boots preserve courtly markers while the landscape and illuminated border disappear.','Subject Matter vs Technique Origin':'The lecture’s preceding reference to Rembrandt suggests European study of Mughal portraits, but this uncaptioned sheet is not securely catalogued by the slide.'},'print-transfer portrait-miniature',sig='visual/aesthetic=The pairing shows what changes when an elaborate court portrait is reinterpreted as a sparse drawing.',dist='The resemblance and preceding mention of Rembrandt support a comparison, not a confirmed attribution of this exact sheet.',compare=[{'target':'Shah Jahan on a Terrace Holding a Portrait Pendant','relationship':'parallel','reason':'The paired display contrasts a densely painted Mughal folio with a sparse linear drawing.'}],uncertain=['Artist and exact drawing identity are not captioned on slide 24.'])
A('','Globe in the Mughal Court','D',{'Argument':'European prints, books and cartographic forms entered Mughal courtly image-making and were selectively adapted. The module asks how foreign visual resources became tools for local political and religious expression.','Evidence':'Christian-themed paintings, the Gulshan composite page, artists’ studies, and Jahangir’s two globe allegories show different mechanisms of transfer.','Course Throughline':'Trade and travel move images and skills as well as goods. Indian-centred cartography and transformed religious imagery make the receiving court an active interpreter.'},'firangi-sazi cartography connected-histories',dist='Circulation does not imply passive copying or uniform adoption of European naturalism.',slides='5:1,4,5,7,10,12,18,19,20,21,23')
A('','Occidentalism and Orientalism — lecture comparison','C',{'Definition':'Slide 4 asks how a Mughal engagement with western images and styles differs from Orientalism. Occidentalism here is a working label for looking toward or representing the West; the slide poses a comparison rather than defining a complete theory.','Nearest Confusable Terms':'Orientalism can name European artistic representations of the East and, in critical theory, systems of knowledge tied to unequal power. These meanings must be separated from a simple compass-direction reversal.','Applied To':'Akbar and Adham Khan introduces the question; Christian adaptations and European print models provide the ensuing cases.'},'orientalism-occidentalism firangi-sazi',dist='Do not assume Occidentalism is an exact political mirror of Orientalism, or that a borrowed European motif proves colonial domination of its Mughal user.',slides='5:4,5,10,12,15,17')
